    fetch('https://api.github.com/repos/Blackcat76iT/OsuNet/releases')
    .then(res => res.json())
    .then(releases => {
        releases.forEach(element => {
            const box = document.createElement('div');
            const box_header = document.createElement('h2');
            const box_body = document.createElement('div');

            box.style.opacity = 0;
            box.classList.add('box');
            box_header.classList.add('box-header');
            box_body.classList.add('box-body')

            box_header.innerText = element['name'];
            box_body.innerHTML = marked.parse(element['body']);

            box.appendChild(box_header);
            box.appendChild(box_body);
            changelog.appendChild(box);
            changeOpacity1(box);
            changeOpacity1(footer);
        });
    });
});

function changeOpacity1(element) {
    let opacity = 0;

    function step() {
        opacity += 0.0125;
        element.style.opacity = opacity;

        if (opacity < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
}
